{"content": "/** @type {import('next').NextConfig} */
const nextConfig = {
  /**
   * APIリクエストをバックエンドサーバーにプロキシする設定
   * - 開発時 (npm run dev): BACKEND_URL=http://backend-app:8080 (docker-compose.dev.yml で指定)
   * - ローカル単独起動時: BACKEND_URL 未指定 → http://localhost:8080 にフォールバック
   */
  async rewrites() {
    const backendUrl = process.env.BACKEND_URL || 'http://localhost:8080'
    return [
      {
        source: '/api/:path*',
        destination: `${backendUrl}/api/:path*`,
      },
    ]
  },
}

module.exports = nextConfig
